func partition(s string) [][]string {
    n := len(s)
    // dp[i][j] 表示 s[i..j] 是否为回文
    dp := make([][]bool, n)
    for i := range dp {
        dp[i] = make([]bool, n)
        dp[i][i] = true
    }
    for l := 2; l <= n; l++ {
        for i := 0; i <= n-l; i++ {
            j := i + l - 1
            if s[i] == s[j] {
                dp[i][j] = l == 2 || dp[i+1][j-1]
            }
        }
    }

    var res [][]string
    var path []string
    var backtrack func(start int)
    backtrack = func(start int) {
        if start == n {
            tmp := make([]string, len(path))
            copy(tmp, path)
            res = append(res, tmp)
            return
        }
        for end := start; end < n; end++ {
            if dp[start][end] {
                path = append(path, s[start:end+1])
                backtrack(end + 1)
                path = path[:len(path)-1]
            }
        }
    }
    backtrack(0)
    return res
}
